use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,path::Path};
const R:&str="/home/ubuntu/src/zopro-perf-work/joint-top-count175";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap();}
fn main(){let r=Path::new(R);assert!(!r.join("followup-plan.json").exists());let original=read(r.join("plan.json"));let mut pins=read(r.join("pins.json")).as_object().unwrap().iter().map(|(p,h)|(p.clone(),h.as_str().unwrap().to_string())).collect::<BTreeMap<_,_>>();for(p,h)in &pins{assert_eq!(hash(p),*h);}assert_eq!(read(r.join("runs/result.json"))["status"],"complete");for p in["followup.rs","followup-design.md","followup-setup.rs","followup-setup","plan.json","pins.json","runs/result.json","runs/count-two-fixtures/stdout.log"]{let p=r.join(p);pins.insert(p.display().to_string(),hash(p));}
    let change=|value:&Value,old:&str,new:&str|{let mut a=value.as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_string()).collect::<Vec<_>>();let input=r.join("probe.rs").display().to_string();let output=r.join(old).display().to_string();for v in &mut a{if *v==input{*v=r.join("followup.rs").display().to_string();}else if *v==output{*v=r.join(new).display().to_string();}}a};
    let test=change(&original["steps"][0]["argv"],"tests","coalesced-tests");let probe=change(&original["steps"][2]["argv"],"probe","coalesced-probe");
    let step=|name:&str,argv:Vec<String>|json!({"kind":"command","name":name,"argv":argv,"timeout_seconds":900});
    save(r.join("followup-pins.json"),&json!(pins));save(r.join("followup-plan.json"),&json!({"version":1,"source_pins":r.join("followup-pins.json"),"steps":[step("compile-coalesced-tests",test),step("test-coalesced-model",vec![r.join("coalesced-tests").display().to_string(),"followup_tests::".into(),"--test-threads=1".into()]),step("compile-coalesced-probe",probe),step("count-coalesced-top",vec![r.join("coalesced-probe").display().to_string()])]}));println!("Prepared four separate follow-up steps; {} pins; original workflow and gate retained",pins.len());}
